"""Exam-tier source for `cyclic-group-element-order`: the subgroup generated by one element of Z/nZ.

The stem names a modulus n and an element [a], and says H is the subgroup that [a] generates. The learner
has to carry one idea through three questions, the way a first-year algebra paper does:

* (a) the order of [a], which is the size of H: n / gcd(a, n);
* (b) the index of H in Z/nZ, the number of cosets: n divided by the answer to (a);
* (c) how many elements of H generate H, which is Euler's totient of the answer to (a).

Part (b) follows through from (a); (c) needs Euler's totient, which a follow-through expression cannot name, so it
is marked on its own. The draw keeps |H| composite, so (c) is never simply |H| - 1, and
keeps gcd(a, n) > 1, so [a] is not a generator of the whole group. Every key is checked against a brute-force
count: the orbit of [a] under repeated addition, and the elements of H that have the same order as [a].
"""

from __future__ import annotations

import random
from math import gcd

from sympy import isprime, totient

from ..answers import Distractor, exact_value
from ..core import attempts, check, generator, pick_distractors

_STEMS = [
    "Let G be the additive group Z/{n}Z of integers modulo {n}, and let H be the subgroup of G generated by [{a}].",
    "Let G be the group Z/{n}Z under addition, and let H be the subgroup of G generated by the element [{a}].",
    "Let G be the additive group of integers modulo {n}. The element [{a}] of G generates a subgroup H.",
]
_B_PROMPTS = [
    "Find the index of H in G, that is, the number of distinct cosets of H.",
    "How many distinct cosets does H have in G?",
]
_C_PROMPTS = [
    "How many elements of H generate H on their own?",
    "Find the number of generators of H, that is, the elements of H whose order equals |H|.",
]


def _orbit_size(a: int, n: int) -> int:
    """Brute force: how many distinct residues [a], [2a], ... are visited up to and including the return to [0]."""
    seen, current = set(), 0
    for _ in range(n):
        current = (current + a) % n
        seen.add(current)
        if current == 0:
            return len(seen)
    raise RuntimeError("orbit did not close")


_COMPOSITE_ORDERS = [d for d in range(6, 31) if not isprime(d)]


def _draw(rng: random.Random):
    """Draw gcd g, a composite order d, and a unit u mod d: n = g d and a = g u, so gcd(a, n) = g and ord([a]) = d."""
    for _ in attempts(1000, "a modulus and element"):
        g = rng.randint(2, 9)
        d = rng.choice(_COMPOSITE_ORDERS)
        u = rng.randint(1, d - 1)
        if gcd(u, d) == 1:
            return g * d, g * u, g, d
    raise RuntimeError("unreachable")


@generator("exd_x_u1_cyclic_subgroup", level=16, presets={"exam": dict(tier="exam")})
def exd_x_u1_cyclic_subgroup(rng: random.Random, tier: str = "exam") -> dict:
    """Exam tier: order, index and number of generators of the subgroup generated by [a] in Z/nZ."""
    check(tier == "exam", f"unknown tier {tier!r}")
    n, a, g, d = _draw(rng)

    # Independent route: brute-force the orbit, then count the elements of H that have the same order.
    order = _orbit_size(a, n)
    subgroup = {(a * k) % n for k in range(1, n + 1)}
    # [0] has order 1 and is left out; every other element of H is tested for the same order as [a].
    generators = sum(1 for h in subgroup if h != 0 and _orbit_size(h, n) == order)
    index = n // order
    check(order == d == len(subgroup), "order of [a] disagrees with the size of H")
    check(index == g and n % order == 0, "index disagrees with gcd(a, n)")
    check(generators == int(totient(order)), "number of generators disagrees with the totient")
    check(generators not in (order, order - 1), "generator count collides with a familiar slip")

    stem = rng.choice(_STEMS).format(n=n, a=a)

    def tagged(text_value, tag):
        return Distractor(str(text_value), tag, exact_value(text_value))

    a_candidates = [
        tagged(g, "order-reported-as-gcd"),
        tagged(n, "uses-group-size-always"),
        tagged(a, "confuses-element-with-order"),
        tagged(order - 1, None),
    ]
    b_candidates = [
        tagged(order, "index-reported-as-subgroup-order"),
        tagged(n, None),
        tagged(n - order, None),
    ]
    c_candidates = [
        tagged(order, "every-element-of-subgroup-generates"),
        tagged(order - 1, "all-but-identity-generate"),
        tagged(order // 2, None),
        tagged(index, None),
    ]
    a_dist = pick_distractors(str(order), a_candidates, 3)
    b_dist = pick_distractors(str(index), b_candidates, 3)
    c_dist = pick_distractors(str(generators), c_candidates, 3)
    check(len(a_dist) >= 2 and len(b_dist) >= 2 and len(c_dist) >= 2, "too few distractors")

    return dict(
        text=stem,
        parts=[
            dict(
                prompt=f"Find the order of [{a}] in G.",
                answer_kind="number",
                answer=order,
                answer_text=str(order),
                marks=2,
                sensible_range=(0, None),
                working=[
                    f"The order of [{a}] in Z/{n}Z is {n} / gcd({a}, {n}) = {n} / {g} = {order}.",
                ],
                distractors=a_dist,
            ),
            dict(
                prompt=rng.choice(_B_PROMPTS),
                answer_kind="number",
                answer=index,
                answer_text=str(index),
                marks=1,
                sensible_range=(0, None),
                follow_through=f"{n}/part_a",
                working=[f"|G| / |H| = {n} / {order} = {index}."],
                distractors=b_dist,
            ),
            dict(
                prompt=rng.choice(_C_PROMPTS),
                answer_kind="number",
                answer=generators,
                answer_text=str(generators),
                marks=2,
                sensible_range=(0, None),
                working=[
                    f"H is cyclic of order {order}, so its generators are the elements of order {order}.",
                    f"Their number is Euler's totient of {order}, which is {generators}.",
                ],
                distractors=c_dist,
            ),
        ],
    )
